# One small Stan program per family, generated by brms, for the two gradient
# scripts in this directory. Sourced by gradient_check.R and gradient_cost.R;
# not meant to be run on its own.
#
# The programs are what a user would get from brm(): the family's own
# stanvars, cogmod_priors() where the family has them, every distributional
# parameter modelled as an intercept (so it sits on its link scale, the way it
# does in a real fit) except where the tests fix one for identifiability. Data
# are simulated from the family's own r<family>() at its defaults, and - when
# asked - salted with responses out in the tails, because that is where a
# density that is right in the body goes wrong: the LNR's normal tails used to
# underflow around 38 standardized units and hand Stan a NaN gradient, from a
# single 5 s trial.
#
# Everything here reads the package through `cogmod::` / `cogmod:::`, so the
# caller decides which working tree is loaded (pkgload::load_all() on a
# directory) - gradient_cost.R loads the base branch and the PR in turn.

# ---- CLI ---------------------------------------------------------------------

# `--key value` pairs off commandArgs(), with defaults filled in.
gp_args <- function(defaults) {
  a <- commandArgs(trailingOnly = TRUE)
  out <- defaults
  i <- 1
  while (i <= length(a)) {
    key <- sub("^--", "", a[i])
    if (!startsWith(a[i], "--")) stop("unexpected argument: ", a[i], call. = FALSE)
    val <- if (i < length(a) && !startsWith(a[i + 1], "--")) a[i + 1] else "TRUE"
    if (!key %in% names(defaults)) stop("unknown option --", key, call. = FALSE)
    out[[key]] <- methods::as(val, class(defaults[[key]]))
    i <- i + if (identical(val, "TRUE") && (i == length(a) || startsWith(a[i + 1], "--"))) 1 else 2
  }
  out
}

# Load the package from `dir` (a working tree), quietly.
gp_load <- function(dir) {
  suppressPackageStartupMessages(pkgload::load_all(dir, quiet = TRUE, export_all = TRUE))
  invisible(dir)
}

# ---- Families ----------------------------------------------------------------

# Every family constructor the package exports: cogmod_<name>() returning a
# brms custom family. Read off the namespace, so a new family is picked up
# without touching this file.
gp_families <- function() {
  ns <- asNamespace("cogmod")
  nm <- ls(ns, pattern = "^cogmod_[a-z0-9]+$")
  ok <- vapply(nm, function(n) {
    f <- get(n, envir = ns)
    is.function(f) && inherits(try(f(), silent = TRUE), "customfamily")
  }, logical(1))
  sort(nm[ok])
}

# What the response looks like, per family: "rt", "choice", "unit", "rating".
gp_class <- function(fam) {
  cls <- cogmod:::.checkdata_class(fam)
  if (is.null(cls)) stop("no response class for ", fam, call. = FALSE)
  cls
}

# Distributional parameters the tests fix in the formula rather than estimate,
# for identifiability, with the value they fix them at.
.GP_FIXED <- list(
  cogmod_lba1 = c(sigma = 1)
)

# ---- Data --------------------------------------------------------------------

# Simulated responses from r<family>() at its defaults (with a small outlier
# rate where the family has one), as the data frame brm() would take. With
# `extremes`, a handful of tail responses are appended: the fastest possible
# trial and several very slow ones for the RT families, both responses each
# for the choice families; the ends and the middle of the scale for the
# bounded ones.
gp_data <- function(fam, n = 300, seed = 2026, extremes = TRUE) {
  set.seed(seed)
  rng <- get(paste0("r", fam), envir = asNamespace("cogmod"))
  args <- list(n)
  if ("poutlier" %in% names(formals(rng))) args$poutlier <- 0.02
  sim <- do.call(rng, args)
  cls <- gp_class(fam)

  slow <- c(3, 6, 12)
  d <- switch(cls,
    choice = {
      d <- data.frame(RT = sim$rt, Error = as.integer(sim$response))
      if (extremes) {
        fast <- min(d$RT) + 1e-4
        d <- rbind(d, data.frame(RT = rep(c(fast, slow), 2),
                                 Error = rep(0:1, each = 1 + length(slow))))
      }
      d
    },
    rt = {
      d <- data.frame(RT = as.numeric(sim))
      if (extremes) d <- rbind(d, data.frame(RT = c(min(d$RT) + 1e-4, slow)))
      d
    },
    unit = {
      d <- data.frame(y = as.numeric(sim))
      if (extremes) d <- rbind(d, data.frame(y = c(0, 1e-3, 0.5, 1 - 1e-3, 1)))
      d
    },
    rating = {
      k <- formals(rng)$k
      d <- data.frame(y = as.integer(sim), k = as.integer(k))
      if (extremes) d <- rbind(d, data.frame(y = c(0L, as.integer(k)), k = as.integer(k)))
      d
    }
  )
  rownames(d) <- NULL
  d
}

# ---- Formula -----------------------------------------------------------------

# Intercept-only model with every dpar modelled (on its link scale), the
# family's addition term on the response, and the fixed dpars above.
gp_formula <- function(fam) {
  fobj <- get(fam, envir = asNamespace("cogmod"))()
  cls <- gp_class(fam)
  lhs <- switch(cls, choice = "RT | dec(Error)", rt = "RT", unit = "y",
                rating = "y | vint(k)")
  fixed <- .GP_FIXED[[fam]]
  dp <- setdiff(fobj$dpars[-1], names(fixed))
  terms <- lapply(c(paste(lhs, "~ 1"), paste(dp, "~ 1")), stats::as.formula,
                  env = globalenv())
  do.call(brms::bf, c(terms, as.list(fixed), list(family = fobj)))
}

# ---- Program -----------------------------------------------------------------

# The Stan program, data list and (where cogmod_inits() knows the family) one
# starting value list, for one family.
gp_program <- function(fam, n = 300, seed = 2026, extremes = TRUE) {
  d <- gp_data(fam, n = n, seed = seed, extremes = extremes)
  f <- gp_formula(fam)
  # cogmod_priors() says, at length, when it has nothing for a family; the brms
  # defaults it returns then are fine for a gradient at a fixed point.
  prior <- tryCatch(suppressMessages(cogmod::cogmod_priors(f, d)), error = function(e) NULL)
  sv <- tryCatch(cogmod::cogmod_stanvars(f), error = function(e) NULL)
  if (is.null(sv)) sv <- get(paste0(fam, "_stanvars"), envir = asNamespace("cogmod"))()
  init <- if (fam %in% cogmod:::.init_families()) {
    cogmod::cogmod_inits(f, d, jitter = 0)(1)
  } else {
    NULL
  }
  code <- brms::make_stancode(f, data = d, prior = prior, stanvars = sv,
                              backend = "cmdstanr")
  standata <- brms::make_standata(f, data = d, prior = prior, stanvars = sv)
  standata <- lapply(unclass(standata), identity)
  list(family = fam, formula = f, data = d, prior = prior, code = as.character(code),
       standata = standata, init = init)
}

# Write the programs for `families` under `dir`: <family>.stan, <family>.data.json
# and, where there is one, <family>.init.json. Returns one row per family with
# the paths (NA for a missing init).
gp_emit <- function(dir, families = gp_families(), n = 300, seed = 2026,
                    extremes = TRUE, verbose = TRUE) {
  dir.create(dir, recursive = TRUE, showWarnings = FALSE)
  rows <- lapply(families, function(fam) {
    if (verbose) cat(sprintf("  %-22s", fam))
    p <- gp_program(fam, n = n, seed = seed, extremes = extremes)
    stan <- file.path(dir, paste0(fam, ".stan"))
    data <- file.path(dir, paste0(fam, ".data.json"))
    init <- file.path(dir, paste0(fam, ".init.json"))
    writeLines(p$code, stan)
    cmdstanr::write_stan_json(p$standata, data)
    if (!is.null(p$init)) cmdstanr::write_stan_json(p$init, init) else init <- NA_character_
    if (verbose) cat(sprintf("N = %d, %d dpars%s\n", p$standata$N,
                             length(p$formula$family$dpars),
                             if (is.na(init)) ", no cogmod_inits()" else ""))
    data.frame(family = fam, stan = stan, data = data, init = init,
               stringsAsFactors = FALSE)
  })
  do.call(rbind, rows)
}

# ---- Model methods -----------------------------------------------------------

# Compile one emitted program with model methods. `dir` gets the executable.
gp_compile <- function(stan, dir = dirname(stan)) {
  cmdstanr::cmdstan_model(stan, compile_model_methods = TRUE, dir = dir,
                          force_recompile = TRUE, quiet = TRUE)
}

# A fitted object with model methods live, at the emitted init (or 0), from a
# one-iteration fixed_param run: the cheapest way to get a CmdStanMCMC that
# log_prob() and grad_log_prob() can hang off. Returns the fit and the init in
# unconstrained space.
gp_methods <- function(mod, data, init = NA_character_) {
  init_arg <- if (is.na(init)) 0 else init
  fit <- mod$sample(data = data, init = init_arg, chains = 1, iter_warmup = 1,
                    iter_sampling = 1, fixed_param = TRUE, refresh = 0,
                    show_messages = FALSE, show_exceptions = FALSE)
  # A failed init surfaces only when the metadata is asked for.
  fit$metadata()
  fit$init_model_methods(verbose = FALSE)
  up0 <- as.numeric(fit$unconstrain_draws(format = "draws_matrix")[1, ])
  list(fit = fit, up0 = up0)
}
